head.script:
scwin.trigger1_onclick = function(e) {
    wframe.setSrc("wframe1_anchorTag_WPF-1340_(WSQ-1949).xml");
};
scwin.trigger2_onclick = function(e) {
    wframe.setSrc("wframe2_anchorTag_WPF-1340_(WSQ-1949).xml");
};
scwin.setValue = function() {
    if (WebSquare.wUnit.getJq('#anchor1').length == 0) {
        WebSquare.wUnit.getDomById('wframe_anchor1').click();
    } else {
        anchor1.click();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 하단의 wframe1버튼을 클릭 후 상단의 anchor button을 클릭한다.
    //1. After running the sample file, click the wframe1 button at the bottom and click the anchor button at the top.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setValue()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 상단에 관련화면이 보여지고 이벤트(wframe1_anchor)가 1번 호출되어 보여진다.(20160928일자 엔진만 이벤트가 2번호출되어 보여짐)
    //1. The related screen is displayed at the top and the event (wframe1_anchor) is called once and is displayed. (20160928 only date engine shows 2 events)
    WebSquare.wUnit.addCommand("assert", "window.count == 1", "true");
    WebSquare.wUnit.addCommand("assert", "window.log", "wframe1_anchor");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 21-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
